const input = $input.item.json || {};
const body = input.body || input;

return {
  json: {
    surah: body.surah || 67,
    startAyah: body.startAyah || 1,
    count: body.count || 5,
    reciterId: body.reciterId || 7,
    theme: body.theme || 'nocturnal_relaxing',
    timestamp: new Date().toISOString()
  }
};

const reel = $input.item.json;
const verses = reel.verses || [];

const arabicFullText = verses.map(v => v.text).join(' ۝ ');
const verseKeys = verses.map(v => v.key).join(', ');

const title = `Surah ${reel.surah} (Ayahs ${verseKeys})`;
const caption = `Surah ${reel.surah} (Ayahs ${verseKeys})\n\n"${arabicFullText}"\n\nReciter: Mishari Rashid Alafasy\n\nRelax your heart and find peace in the words of the Almighty. 🕊️✨\n\n#quran #islam #relaxation #quranrecitation #peace #reels #shorts #tiktok`;

// Determine video URL (prefer public tunnel for Buffer, fallback to local stream)
const videoUrl = reel.public_stream_url || reel.stream_url || `http://localhost:5056/stream/reel_${reel.job_id}.mp4`;

const channels = [
  {
    channelName: "YouTube Shorts",
    channelId: "6af071d462b70b94b0bde992",
    input: {
      channelId: "6af071d462b70b94b0bde992",
      text: caption,
      schedulingType: "automatic",
      mode: "addToQueue",
      needsApproval: false,
      assets: [
        {
          video: {
            url: videoUrl
          }
        }
      ],
      metadata: {
        youtube: {
          title: title.slice(0, 95),
          privacy: "public",
          madeForKids: false,
          categoryId: "22"
        }
      }
    }
  },
  {
    channelName: "TikTok",
    channelId: "6af072a762b70b94b0be017e",
    input: {
      channelId: "6af072a762b70b94b0be017e",
      text: caption,
      schedulingType: "automatic",
      mode: "addToQueue",
      needsApproval: false,
      assets: [
        {
          video: {
            url: videoUrl
          }
        }
      ],
      metadata: {
        tiktok: {
          title: title.slice(0, 90),
          isAiGenerated: false
        }
      }
    }
  },
  {
    channelName: "Facebook Reels",
    channelId: "6af0714462b70b94b0bde62b",
    input: {
      channelId: "6af0714462b70b94b0bde62b",
      text: caption,
      schedulingType: "automatic",
      mode: "addToQueue",
      needsApproval: false,
      assets: [
        {
          video: {
            url: videoUrl
          }
        }
      ],
      metadata: {
        facebook: {
          type: "reel"
        }
      }
    }
  }
];

return channels.map(c => ({
  json: {
    channelName: c.channelName,
    channelId: c.channelId,
    job_id: reel.job_id,
    surah: reel.surah,
    verses: verseKeys,
    public_stream_url: videoUrl,
    input: c.input
  }
}));

